-- Haskell 2010 Report 6.3.4: class Enum at Int and Integer; succ, pred, toEnum, fromEnum, enumFrom[Then][To]
main :: IO ()
main = do
  print ("succ/pred Int", succ (1 :: Int), pred (1 :: Int), succ (-1 :: Int), pred (0 :: Int))
  print ("succ/pred Integer", succ (2 ^ (64 :: Int) :: Integer), pred (0 :: Integer), pred (negate (2 ^ (64 :: Int)) :: Integer))
  print ("toEnum/fromEnum Int", toEnum 65 :: Int, fromEnum (65 :: Int), fromEnum (-3 :: Int), fromEnum (maxBound :: Int) == maxBound)
  print ("toEnum/fromEnum Integer", toEnum 7 :: Integer, fromEnum (7 :: Integer), fromEnum (-3 :: Integer))
  print ("enumFromTo", [1 .. 5 :: Int], enumFromTo 1 (5 :: Int), [3 .. 3 :: Int], [5 .. 1 :: Int], [-2 .. 2 :: Int])
  print ("enumFromThenTo up", [1, 3 .. 10 :: Int], [1, 3 .. 9 :: Int], [0, 5 .. 20 :: Int], [1, 3 .. 1 :: Int], [1, 3 .. 0 :: Int])
  print ("enumFromThenTo down", [5, 3 .. 0 :: Int], [10, 8 .. 1 :: Int], [5, 4 .. 5 :: Int], [5, 4 .. 6 :: Int], [0, -1 .. -3 :: Int])
  print ("enumFromThenTo big steps", [1, 100 .. 150 :: Int], [1, 100 .. 99 :: Int], [10, 0 .. -5 :: Int], [10, 0 .. 1 :: Int])
  print ("zero step", take 3 [4, 4 .. 4 :: Int], take 3 [4, 4 .. 9 :: Int], [4, 4 .. 3 :: Int])
  print ("enumFrom", take 4 (enumFrom (10 :: Int)), take 4 [(-2 :: Int) ..], take 3 [(2 :: Integer) ^ (64 :: Int) ..])
  print ("enumFromThen", take 4 (enumFromThen 10 (7 :: Int)), take 4 [(1 :: Int), 3 ..], take 3 [(0 :: Integer), -10 ..])
  print ("Int enumFrom stops at maxBound", length [(maxBound :: Int) - 2 ..], last [(maxBound :: Int) - 2 ..] == maxBound)
  print ("Int enumFromThen stops at bounds", length [(maxBound :: Int) - 1, maxBound ..], length [(minBound :: Int) + 1, minBound ..])
  print ("Int enumFromThen stops short of maxBound", length [(maxBound :: Int) - 5, maxBound - 2 ..])
  print ("Integer ranges", [2 ^ (64 :: Int) .. 2 ^ (64 :: Int) + 2 :: Integer])
  print ("Integer stepped", length [10 ^ (20 :: Int), 10 ^ (20 :: Int) - 10 ^ (19 :: Int) .. 0 :: Integer])
  print ("Integer negative", [-3 .. 0 :: Integer], [0, -2 .. -7 :: Integer], [5, 5 .. 4 :: Integer])
  print ("method forms", enumFromThenTo 1 4 (14 :: Int), enumFromTo (-1) (1 :: Integer), map fromEnum [1, 2 :: Int])
  print ("sums", sum [1 .. 100 :: Int], sum [1, 3 .. 99 :: Integer], length [1 .. 10000 :: Int])
  print ("ranges are lazy", take 2 [1 .. (maxBound :: Int)], head [5, 10 .. 10 ^ (30 :: Int) :: Integer])
  print ("map toEnum . fromEnum", map (toEnum . fromEnum) [1, 2, 3 :: Int] :: [Integer])
